; CHR ROM (128KB = 16 x 8KB, MMC3 1KB/2KB banks). Generated by tools/disasm.py.
; The files are written by tools/chr_tool.py split (gfx/chr_XX.png are the editable sheets).

.segment "CHR_ROM"
  .incbin "chr/chr_00.chr"                ; CHR $00000-$01FFF
  .incbin "chr/chr_01.chr"                ; CHR $02000-$03FFF
  .incbin "chr/chr_02.chr"                ; CHR $04000-$05FFF
  .incbin "chr/chr_03.chr"                ; CHR $06000-$07FFF
  .incbin "chr/chr_04.chr"                ; CHR $08000-$09FFF
  .incbin "chr/chr_05.chr"                ; CHR $0A000-$0BFFF
  .incbin "chr/chr_06.chr"                ; CHR $0C000-$0DFFF
  .incbin "chr/chr_07.chr"                ; CHR $0E000-$0FFFF
  .incbin "chr/chr_08.chr"                ; CHR $10000-$11FFF
  .incbin "chr/chr_09.chr"                ; CHR $12000-$13FFF
  .incbin "chr/chr_0A.chr"                ; CHR $14000-$15FFF
  .incbin "chr/chr_0B.chr"                ; CHR $16000-$17FFF
  .incbin "chr/chr_0C.chr"                ; CHR $18000-$19FFF
  .incbin "chr/chr_0D.chr"                ; CHR $1A000-$1BFFF
  .incbin "chr/chr_0E.chr"                ; CHR $1C000-$1DFFF
  .incbin "chr/chr_0F.chr"                ; CHR $1E000-$1FFFF
